function SolanaProviders({ children }: { children: ReactNode }) {
  const endpoint = useMemo(() => clusterApiUrl('devnet'), [])
  const wallets = useMemo(() => [new PhantomWalletAdapter(), new SolflareWalletAdapter()], [])

  return (
    <ConnectionProvider endpoint={endpoint}>
      <WalletProvider wallets={wallets} autoConnect>
        <WalletModalProvider>{children}</WalletModalProvider>
      </WalletProvider>
    </ConnectionProvider>
  )
}

const apiUrl = import.meta.env.VITE_API_URL ?? '/api'
type DemoSession = { token: string; user: { id: string; email: string; displayName: string; role: 'client' | 'freelancer'; organizationId?: string } }
const sessionKey = 'componere-session'
const readSession = () => { try { return JSON.parse(localStorage.getItem(sessionKey) ?? 'null') as DemoSession | null } catch { return null } }
const authHeaders = (session: DemoSession | null) => session ? { authorization: `Bearer ${session.token}` } : {}
async function apiRequest<T>(path: string, init: RequestInit = {}, session = readSession()): Promise<T> {
  const response = await fetch(`${apiUrl}${path}`, { ...init, headers: { ...authHeaders(session), ...(init.headers ?? {}) } })
  const body = await response.json().catch(() => ({})) as T & { error?: string }
  if (!response.ok) throw new Error(body.error ?? `Request failed (${response.status})`)
  return body
}
type ApiMilestone = { id: string; amountBaseUnits: string; status: string; evidence?: string[]; submittedBy?: string }
type ApiAgreement = { id: string; organizationId: string; clientId: string; providerId: string; state: string; revisions: { terms: { title?: string; description?: string; label?: string } }[]; milestones: ApiMilestone[]; events?: { event: string; actor_id: string }[] }
const agreementForUi = (item: ApiAgreement): Agreement => {
  const terms = item.revisions[0]?.terms ?? {}
  const amount = item.milestones.reduce((sum, milestone) => sum + Number(milestone.amountBaseUnits) / 1_000_000, 0)
  const status: Agreement['status'] = item.state === 'completed' ? 'completed' : item.state === 'in_progress' || item.state.includes('submitted') || item.state.includes('approval') ? 'active' : item.state === 'funded' ? 'funded' : 'draft'
  return { id: item.id, title: terms.title ?? item.id, counterparty: item.providerId, initials: item.providerId.slice(0, 2).toUpperCase(), amount, status, updated: 'Just now', description: terms.description ?? '', milestones: item.milestones.map(milestone => ({ id: milestone.id, title: milestone.id.replaceAll('-', ' '), amount: Number(milestone.amountBaseUnits) / 1_000_000, due: 'See agreement terms', status: milestone.status === 'released' ? 'released' : milestone.status === 'submitted' || milestone.status === 'approved' ? 'submitted' : 'upcoming', criteria: milestone.evidence?.[0] ?? 'Acceptance criteria recorded in the agreement.' })) }
}

export default function App() { return <SolanaProviders><BrowserRouter><Routes><Route path="/" element={<Landing />} /><Route path="/login" element={<DemoLogin />} /><Route path="/app/*" element={<AuthGate />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></BrowserRouter></SolanaProviders> }
function AuthGate() { const [state, setState] = useState<'loading' | 'ready' | 'signed-out'>('loading'); useEffect(() => { const session = readSession(); if (!session) { setState('signed-out'); return } void apiRequest<{ user: DemoSession['user'] }>('/auth/me', {}, session).then(() => setState('ready')).catch(() => { localStorage.removeItem(sessionKey); setState('signed-out') }) }, []); if (state === 'signed-out') return <Navigate to="/login" replace />; return state === 'loading' ? <div className="blank-state"><h3>Loading authenticated workspace…</h3></div> : <ApiShell /> }
function ApiShell() {
  const session = readSession()
  const [menu, setMenu] = useState(false)
  return <div className="app-frame"><div className="demo-banner"><strong>TESTNET ONLY · AUTHENTICATED</strong><span>{session?.user.displayName} · {session?.user.role}</span><button className="text-link" onClick={() => { void apiRequest('/auth/logout', { method: 'POST' }, session).catch(() => undefined); localStorage.removeItem(sessionKey); window.location.assign('/login') }}>Sign out</button></div><header className="app-topbar"><button className="mobile-menu" onClick={() => setMenu(!menu)}><Menu size={20} /></button><Link to="/app/overview" className="wordmark app-wordmark"><span className="logo-mark">C</span> componere<span className="logo-ai">AI</span></Link><div className="org-switcher"><span className="org-avatar">{session?.user.displayName.slice(0, 2).toUpperCase()}</span><span><b>{session?.user.displayName}</b><small>{session?.user.role} workspace</small></span></div><div className="app-top-actions"><SolanaWalletPanel /><span className="user-avatar">{session?.user.displayName.slice(0, 2).toUpperCase()}</span></div></header><div className={`app-content ${menu ? 'mobile-open' : ''}`}><Sidebar close={() => setMenu(false)} /><main className="app-main"><Routes><Route path="overview" element={<ApiOverview />} /><Route path="agreements" element={<ApiAgreements />} /><Route path="agreements/new" element={<ApiNewAgreement />} /><Route path="agreements/:id" element={<ApiDetails />} /><Route path="escrows" element={<ApiAgreementSection kind="escrows" />} /><Route path="transactions" element={<ApiAgreementSection kind="transactions" />} /><Route path="analytics" element={<ApiAgreementSection kind="analytics" />} /><Route path="team" element={<ApiTeam />} /><Route path="settings" element={<ApiSettings />} /><Route path="*" element={<Navigate to="overview" replace />} /></Routes></main></div></div>
}

